UPDATE partsupp SET ps_supplycost = ps_supplycost + 0.17 WHERE (ps_partkey, ps_suppkey) IN (SELECT DISTINCT ps.ps_partkey, ps.ps_suppkey FROM partsupp ps JOIN lineitem l ON l.l_partkey = ps.ps_partkey AND l.l_suppkey = ps.ps_suppkey JOIN part p ON p.p_partkey = l.l_partkey JOIN orders o ON o.o_orderkey = l.l_orderkey JOIN supplier s ON s.s_suppkey = l.l_suppkey JOIN nation n ON n.n_nationkey = s.s_nationkey WHERE p.p_name LIKE '%green%' ORDER BY ps.ps_partkey, ps.ps_suppkey LIMIT 8);
